-- =====================================================================
-- TamilTO businesses, part 1 of 5 (checklist step 16)
-- Run parts 1, 2, 3, 4 and 5 in order: Supabase → SQL Editor → New query → paste → Run.
-- 4044 GTA businesses in total from the merged Vanikam + Vanakkam Canada list,
-- duplicates merged. ALL HIDDEN: nothing shows on the site until a business has
-- 3 photos and you switch it on in the admin.
-- =====================================================================

begin;

-- Safety check: this replaces the first test import. It refuses to run once real work exists
-- (a live business, a photo, a claim or a quote request), so it can never wipe that out.
do $$
begin
  if exists (select 1 from public.businesses where not is_hidden)
     or exists (select 1 from public.business_photos)
     or exists (select 1 from public.claims)
     or exists (select 1 from public.lead_recipients) then
    raise exception 'Stopped: the database already has live businesses, photos, claims or quote requests. Ask Claude before importing again.';
  end if;
end $$;

-- Clear any earlier import so this merged list replaces it.
delete from public.journeys;
delete from public.collections;
delete from public.businesses;

on conflict (slug) do nothing;

select 'Part 1 of 5 done: ' || (select count(*) from public.businesses) || ' businesses so far. Now run part 2.' as next_step;

commit;
